-- Seed: the full 49-piece catalogue (extracted from the site 2026-11-27).
-- Prices/MRP are NULL on purpose: Saba enters her real prices in her admin.
-- Safe to re-run: existing rows are updated in place.
on conflict (id) do update set name = excluded.name, category = excluded.category, description = excluded.description, finish = excluded.finish, stones = excluded.stones, stock = excluded.stock, photos = excluded.photos, videos = excluded.videos, sort = excluded.sort;
